def balanced(s):
    """Return True if all brackets in s are balanced, ignoring quoted text."""
    stack = []
    matching_open = {
        ')': '(',
        ']': '[',
        '}': '{',
    }

    i = 0
    n = len(s)
    while i < n:
        ch = s[i]

        if ch == '"':
            i += 1
            string_closed = False
            while i < n:
                if s[i] == '\\':
                    i += 2
                elif s[i] == '"':
                    i += 1
                    string_closed = True
                    break
                else:
                    i += 1
            if not string_closed:
                return False
            continue

        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != matching_open[ch]:
                return False
            stack.pop()

        i += 1

    return not stack
